// Independent ICU79.1 comparison oracle; never exports production weights.
#define SOUNIO_CLDR_BUILD_NO_MAIN
#include "cldr_build.cpp"
#include <unicode/ucol.h>
#include <unicode/ustring.h>
#include <unicode/ulocdata.h>
#include <iomanip>
using Gkey=std::vector<std::vector<std::uint64_t>>;
void g_oracle_versions(){UVersionInfo icu{},unicode{},cldr{};u_getVersion(icu);u_getUnicodeVersion(unicode);UErrorCode e=U_ZERO_ERROR;ulocdata_getCLDRVersion(cldr,&e);if(U_FAILURE(e)||icu[0]!=79||icu[1]!=1||unicode[0]!=18||unicode[1]!=0||unicode[2]!=0||cldr[0]!=49)bad("expected ICU79.1 Unicode18 CLDR49 oracle");}
std::vector<UChar> g_utf16(const Fseq&s){std::vector<UChar> out;for(auto cp:s){if(cp<=0xffff)out.push_back(cp);else{out.push_back(0xd800+((cp-0x10000)>>10));out.push_back(0xdc00+((cp-0x10000)&1023));}}return out;}
std::vector<UChar> g_source(const std::string&s){std::vector<UChar> out;auto input=fliteral(s);for(auto cp:input){if(cp<=0xffff)out.push_back(cp);else{out.push_back(0xd800+((cp-0x10000)>>10));out.push_back(0xdc00+((cp-0x10000)&1023));}}return out;}
UCollator* g_compile(const Tailoring&t){auto text=g_source(t.source_rules);UErrorCode status=U_ZERO_ERROR;UParseError parse{};auto c=ucol_openRules(text.empty()?u"":text.data(),static_cast<int32_t>(text.size()),UCOL_DEFAULT,static_cast<UCollationStrength>(UCOL_DEFAULT),&parse,&status);if(U_FAILURE(status))bad("ICU oracle rules "+t.locale+"/"+t.type+": "+u_errorName(status)+" at "+std::to_string(parse.offset));return c;}
std::vector<std::uint8_t> g_icu_key(UCollator*c,const Fseq&input){auto text=g_utf16(input);auto n=ucol_getSortKey(c,text.empty()?u"":text.data(),static_cast<int32_t>(text.size()),nullptr,0);if(n<1)bad("ICU key extent");std::vector<std::uint8_t> out(static_cast<std::size_t>(n));if(ucol_getSortKey(c,text.empty()?u"":text.data(),static_cast<int32_t>(text.size()),out.data(),n)!=n)bad("ICU key extent changed");return out;}
struct Gprepared{std::array<std::vector<std::uint64_t>,4> w;Ggroups groups;Fcp variable_top=0;explicit Gprepared(const Fbuilder&b):groups(b){for(unsigned i=0;i<4;++i)w[i]=b.order[i].weights();set_variable(b.settings.max_variable);}void set_variable(const std::string&kind){const std::map<std::string,std::string> next{{"space","punct"},{"punct","symbol"},{"symbol","currency"},{"currency","digit"}};auto found=next.find(kind);if(found==next.end())bad("maxVariable oracle option");for(const auto&[start,name]:groups.starts)if(name==found->second){if(!start)bad("maxVariable zero bound");variable_top=start-1;return;}bad("maxVariable missing group boundary");}};
Gkey g_key(Fbuilder&b,const Fseq&input,const Gprepared&prepared){
 auto normalized=b.normalizer.nfd(input);auto ces=b.lookup(normalized);const auto&w=prepared.w;const auto&groups=prepared.groups;Gkey out(5);std::vector<std::uint64_t> secondary;bool shifted=false;
 auto append_p=[&](std::vector<std::uint64_t>&target,const Gce&ce){target.push_back(groups.group(b.order[0].nodes[ce.w[0]].original));target.push_back(w[0][ce.w[0]]);};
 auto flush=[&](){if(b.settings.backwards)std::reverse(secondary.begin(),secondary.end());out[1].insert(out[1].end(),secondary.begin(),secondary.end());secondary.clear();};
 for(const auto&ce:ces){auto primary=b.order[0].nodes[ce.w[0]].original;bool separator=primary==0x02000000&&w[0][ce.w[0]]==static_cast<std::uint64_t>(0x02000000)*4194304;bool variable=ce.w[0]&&!separator&&primary<=prepared.variable_top;if(separator){flush();shifted=false;}
  if(b.settings.shifted&&variable){shifted=true;append_p(out[4],ce);continue;}if(b.settings.shifted&&shifted&&!ce.w[0])continue;if(ce.w[0])shifted=false;
  if(ce.w[0])append_p(out[0],ce);if(ce.w[1]){if(separator)out[1].push_back(w[1][ce.w[1]]);else secondary.push_back(w[1][ce.w[1]]);}
  unsigned casing=ce.casing==2?3:ce.casing==1?2:1;if(b.settings.case_first==2)casing=4-casing;
  if(b.settings.case_level){if(b.settings.strength==1?ce.w[0]!=0:ce.w[0]!=0||ce.w[1]!=0)out[2].push_back(casing);}
  if(ce.w[2]){auto t=w[2][ce.w[2]];if(!b.settings.case_level&&b.settings.case_first){auto c=!ce.w[0]&&!ce.w[1]?3U:casing;out[3].push_back(c);out[3].push_back(t);}else out[3].push_back(t);}
  if(b.settings.shifted){out[4].push_back(groups.rank.size()+3);out[4].push_back(ce.w[3]?w[3][ce.w[3]]:0);}else if(b.settings.strength>=4&&(ce.w[0]||ce.w[1]||ce.w[2]||ce.w[3]))out[4].push_back(ce.w[3]?w[3][ce.w[3]]+1:1);
 }
 flush();if(b.settings.strength<4)out[4].clear();if(b.settings.strength<3)out[3].clear();if(b.settings.strength<2)out[1].clear();if(b.settings.strength==5){std::vector<std::uint64_t> identical;for(auto cp:normalized)identical.push_back(cp==0xfffe?1:static_cast<std::uint64_t>(cp)+2);out.push_back(std::move(identical));}
#ifdef SOUNIO_CLDR_WRONG_PRIMARY_ORACLE_CONTROL
 out[0].clear();
#endif
 return out;
}
std::string display(const Fseq&s){std::ostringstream out;for(auto cp:s)out<<std::hex<<cp<<',';return out.str();}
#ifndef SOUNIO_CLDR_GRAPH_ORACLE_NO_MAIN
int main(int argc,char**argv){try{if(argc<3||argc>5)return 64;g_oracle_versions();cldr_input_versions(argv[1],argv[2]);bool full_options=argc==5;unsigned part=full_options?static_cast<unsigned>(std::stoul(argv[3])):0;unsigned parts=full_options?static_cast<unsigned>(std::stoul(argv[4])):1;if(!parts||part>=parts)return 64;Fractional f(fs::path(argv[1])/"common/uca/FractionalUCA.txt");Fnormalize n(argv[2]);Registry registry(argv[1]);std::uint64_t comparisons=0,entries=0;for(std::size_t id=0;id<registry.entries.size();++id){const auto&t=registry.entries[id];if(argc==4&&t.locale!=argv[3])continue;if(full_options&&id%parts!=part)continue;Fbuilder b(f,n);b.apply(registry,id);auto oracle=g_compile(t);std::set<Fseq> samples={{},{0},{0x61,0xfffe,0x62},{0x62,0xfffe,0x61},{0x61,0x301,0xfffe,0x62,0x300},{0x61,0x300,0xfffe,0x62,0x301},{0x20},{0x21},{0x24},{0x2b},{0x61},{0x41},{0x61,0x301},{0xe9},{0x65,0x301},{0xfffe},{0xffff},{0x1f600},{0x4e00},{0x3400},{0x378},{0x627},{0x3b1},{0x430},{0x3042},{0x30a2}};
  std::set<std::size_t> sample_visited;std::function<void(std::size_t)> add_rules=[&](std::size_t entry){if(!sample_visited.insert(entry).second)return;for(const auto&r:registry.entries[entry].rules){if(r.op==4){add_rules(registry.imported(r.text));continue;}if(r.op!=2)continue;if(r.starred){for(auto cp:fstarred(r.text))samples.insert({cp});}else{auto text=fliteral(r.text);samples.insert(text);if(!r.prefix.empty()){auto p=fliteral(r.prefix);p.insert(p.end(),text.begin(),text.end());samples.insert(p);}if(!r.extension.empty())samples.insert(fliteral(r.extension));}}};add_rules(id);
  if(t.locale=="root"&&t.type=="standard"){for(const auto&[key,ces]:f.entries){(void)ces;auto p=key.prefix;p.insert(p.end(),key.text.begin(),key.text.end());samples.insert(std::move(p));}for(auto cp:f.radical)samples.insert({cp});}

  for(const auto&sample:samples)b.lookup(n.nfd(sample));Gprepared prepared(b);
  std::vector<Gsettings> configurations{b.settings};if(full_options){configurations.clear();for(unsigned strength=1;strength<=5;++strength)for(unsigned alternate=0;alternate<2;++alternate)for(unsigned backwards=0;backwards<2;++backwards)for(unsigned case_level=0;case_level<2;++case_level)for(unsigned case_first=0;case_first<3;++case_first)for(const auto&max_variable:std::vector<std::string>{"space","punct","symbol","currency"}){auto config=b.settings;config.strength=strength;config.shifted=alternate!=0;config.backwards=backwards!=0;config.case_level=case_level!=0;config.case_first=case_first;config.max_variable=max_variable;configurations.push_back(config);}}
  for(const auto&config:configurations){b.settings=config;prepared.set_variable(config.max_variable);if(full_options){UErrorCode e=U_ZERO_ERROR;ucol_setAttribute(oracle,UCOL_STRENGTH,config.strength==5?UCOL_IDENTICAL:static_cast<UColAttributeValue>(config.strength-1),&e);ucol_setAttribute(oracle,UCOL_ALTERNATE_HANDLING,config.shifted?UCOL_SHIFTED:UCOL_NON_IGNORABLE,&e);ucol_setAttribute(oracle,UCOL_FRENCH_COLLATION,config.backwards?UCOL_ON:UCOL_OFF,&e);ucol_setAttribute(oracle,UCOL_CASE_LEVEL,config.case_level?UCOL_ON:UCOL_OFF,&e);ucol_setAttribute(oracle,UCOL_CASE_FIRST,config.case_first==2?UCOL_UPPER_FIRST:config.case_first==1?UCOL_LOWER_FIRST:UCOL_OFF,&e);ucol_setAttribute(oracle,UCOL_NORMALIZATION_MODE,UCOL_ON,&e);const std::map<std::string,UColReorderCode> variable{{"space",UCOL_REORDER_CODE_SPACE},{"punct",UCOL_REORDER_CODE_PUNCTUATION},{"symbol",UCOL_REORDER_CODE_SYMBOL},{"currency",UCOL_REORDER_CODE_CURRENCY}};ucol_setMaxVariable(oracle,variable.at(config.max_variable),&e);if(U_FAILURE(e))bad("ICU options "+std::string(u_errorName(e)));}
   std::vector<std::pair<std::vector<std::uint8_t>,Fseq>> sorted;for(const auto&sample:samples)sorted.emplace_back(g_icu_key(oracle,sample),sample);std::sort(sorted.begin(),sorted.end());
   for(std::size_t i=1;i<sorted.size();++i){auto a=g_key(b,sorted[i-1].second,prepared),z=g_key(b,sorted[i].second,prepared);int expected=sorted[i-1].first<sorted[i].first?-1:0;int actual=a<z?-1:z<a?1:0;if(expected!=actual){std::cerr<<"LEFT "<<display(sorted[i-1].second)<<" RIGHT "<<display(sorted[i].second)<<" expected="<<expected<<" actual="<<actual<<"\nOPTIONS strength="<<config.strength<<" shifted="<<config.shifted<<" backwards="<<config.backwards<<" case_level="<<config.case_level<<" case_first="<<config.case_first<<" maxVariable="<<config.max_variable<<"\n";for(const auto&k:{a,z}){std::cerr<<"KEY ";for(const auto&level:k){std::cerr<<"[";for(auto value:level)std::cerr<<std::hex<<value<<",";std::cerr<<"]";}std::cerr<<"\n";}bad("CE graph ordering "+Registry::identity(t.locale,t.type,t.variant));}++comparisons;}
  }
  ucol_close(oracle);++entries;std::cout<<"CLDR_CE_GRAPH_ORACLE_ENTRY_OK "<<Registry::identity(t.locale,t.type,t.variant)<<" samples="<<samples.size()<<"\n";
 }if(!entries||!comparisons)bad("empty graph oracle");std::cout<<"CLDR_CE_GRAPH_ORACLE_OK entries="<<entries<<" comparisons="<<comparisons<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"CLDR_CE_GRAPH_ORACLE_ERROR "<<e.what()<<"\n";return 1;}}
#endif
